for gid, (title, text) in GUIDE.items():
    UK[f"guide.amethystmod.{gid}.title"] = title
    UK[f"guide.amethystmod.{gid}.text"] = text

UK.update(json.loads((Path(__file__).resolve().parent / "_story_uk.json").read_text(encoding="utf-8")))
en = json.loads((LANG / "en_us.json").read_text(encoding="utf-8"))
out = {}
missing = []
for key in en:
    if key in UK:
        out[key] = UK[key]
    else:
        out[key] = en[key]
        missing.append(key)
(LANG / "uk_ua.json").write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
print(f"uk_ua written, {len(missing)} keys fall back to English" + (": " + ", ".join(missing) if missing else ""))
